package cn.bugstack.ai.infrastructure.persistence;

import cn.bugstack.ai.domain.agent.adapter.repository.IRuntimeObservationRepository;
import com.alibaba.fastjson.JSON;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.beans.factory.annotation.Value;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;

@Repository
public class JdbcRuntimeObservationRepository implements IRuntimeObservationRepository {
    private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final RuntimeInstanceIdentity runtimeInstance;
    @Value("${ai.agent.model-pricing.input-per-million:0}") private double inputPricePerMillion;
    @Value("${ai.agent.model-pricing.output-per-million:0}") private double outputPricePerMillion;
    public JdbcRuntimeObservationRepository(JdbcTemplate jdbc,TransactionTemplate tx,RuntimeInstanceIdentity runtimeInstance){this.jdbc=jdbc;this.tx=tx;this.runtimeInstance=runtimeInstance;}

    @Override public void invocationStarted(String id,String session,String user,String root,long at){
        invocationStarted(id,session,user,root,root,at);
    }
    @Override public void invocationStarted(String id,String session,String user,String root,String appName,long at){
        List<Map<String,Object>> conversations=jdbc.query("select id,current_checkpoint_id from conversation where adk_session_id=?",(rs,n)->{Map<String,Object> row=new HashMap<>();row.put("id",rs.getObject("id",UUID.class));row.put("checkpoint",rs.getObject("current_checkpoint_id",UUID.class));return row;},session);
        UUID conversation=conversations.isEmpty()?null:(UUID)conversations.get(0).get("id");
        UUID checkpoint=conversations.isEmpty()?null:(UUID)conversations.get(0).get("checkpoint");
        int inserted=jdbc.update("insert into agent_invocation(id,conversation_id,adk_session_id,root_agent_name,status,started_at,worker_instance_id,heartbeat_at) values (?,?,?,?,'RUNNING',?,?,?) on conflict(id) do nothing",id,conversation,session,root,new Timestamp(at),runtimeInstance.id(),new Timestamp(at));
        if(inserted==1&&conversation!=null){
            UUID task=null;
            if(checkpoint!=null){List<UUID> existing=jdbc.query("select id from agent_task where conversation_id=? and current_checkpoint_id=? order by created_at desc limit 1",(rs,n)->rs.getObject(1,UUID.class),conversation,checkpoint);if(!existing.isEmpty())task=existing.get(0);}
            if(task==null){task=UUID.randomUUID();jdbc.update("insert into agent_task(id,conversation_id,adk_session_id,title,task_type,status,current_invocation_id,current_checkpoint_id) values (?,?,?,?,'GENERAL','RUNNING',?,?)",task,conversation,session,appName,id,checkpoint);}
            else jdbc.update("update agent_task set status='RUNNING',current_invocation_id=?,completed_at=null,updated_at=now(),version=version+1 where id=?",id,task);
            jdbc.update("update agent_invocation set task_id=? where id=?",task,id);jdbc.update("update conversation set current_invocation_id=?,status='RUNNING',updated_at=now(),version=version+1 where id=?",id,conversation);workflowTransition(task,checkpoint,id,"RUNNING");
        }
        runtimeEvent(session,id,"INVOCATION_STARTED",Map.of("rootAgent",root,"userId",user));
    }
    @Override public void invocationCompleted(String id,String status,long completed,long duration,long input,long output,String error){
        tx.executeWithoutResult(transaction->{
            Timestamp ended=new Timestamp(completed);
            int changed=jdbc.update("update agent_invocation set status=?,completed_at=?,duration_ms=?,input_tokens=?,output_tokens=?,estimated_cost=(select coalesce(sum(estimated_cost),0) from model_call where invocation_id=?),error_message=?,version=version+1 where id=? and status='RUNNING'",status,ended,duration,input,output,id,error,id);
            // Recovery may already have committed INTERRUPTED/FAILED. A late reactive callback must not resurrect it.
            if(changed==0)return;
            jdbc.update("update agent_task set status=?,completed_at=?,updated_at=now(),version=version+1 where current_invocation_id=? and status='RUNNING'",status,ended,id);
            String childStatus="SUCCESS".equals(status)?"SUCCESS":"ERROR";
            jdbc.update("update agent_run set status=?,completed_at=?,duration_ms=coalesce(duration_ms,?),error_message=coalesce(error_message,?),version=version+1 where invocation_id=? and status='RUNNING'",childStatus,ended,duration,error,id);
            jdbc.update("update agent_run_step set status=?,completed_at=?,duration_ms=coalesce(duration_ms,?),error_message=coalesce(error_message,?) where invocation_id=? and status='RUNNING'",childStatus,ended,duration,error,id);
            jdbc.update("update model_call set status=?,completed_at=?,duration_ms=coalesce(duration_ms,?),error_message=coalesce(error_message,?) where invocation_id=? and status='RUNNING'",childStatus,ended,duration,error,id);
            jdbc.update("update tool_execution set status=?,completed_at=?,duration_ms=coalesce(duration_ms,?),error_message=coalesce(error_message,?) where invocation_id=? and status='RUNNING'",childStatus,ended,duration,error,id);
            String session=session(id);if(session!=null)runtimeEvent(session,id,"INVOCATION_COMPLETED",Map.of("status",status,"durationMs",duration,"inputTokens",input,"outputTokens",output));
        });
    }
    @Override public void bindInvocationRequest(String invocation,String requestId){
        if(requestId==null||requestId.isBlank())return;
        tx.executeWithoutResult(status->{
            jdbc.query("select pg_advisory_xact_lock(hashtext(?))",rs->null,requestId);
            List<Map<String,Object>> previous=jdbc.query("select id,attempt_no from agent_invocation where adk_session_id=(select adk_session_id from agent_invocation where id=?) and request_id=? and id<>? order by attempt_no desc limit 1",(rs,n)->Map.of("id",rs.getString(1),"attempt",rs.getInt(2)),invocation,requestId,invocation);
            int attempt=previous.isEmpty()?1:((Number)previous.get(0).get("attempt")).intValue()+1;
            String retryOf=previous.isEmpty()?null:String.valueOf(previous.get(0).get("id"));
            jdbc.update("update agent_invocation set request_id=?,attempt_no=?,retry_of_invocation_id=? where id=? and request_id is null",requestId,attempt,retryOf,invocation);
        });
    }
    @Override public void invocationVersionSnapshot(String invocation,Map<String,Object> snapshot){jdbc.update("update agent_invocation set version_snapshot=cast(? as jsonb),prompt_version=?,agent_config_version=?,model_version=? where id=?",JSON.toJSONString(snapshot),snapshot.get("promptVersion"),snapshot.get("agentConfigVersion"),snapshot.get("modelVersion"),invocation);}
    @Override public void invocationModelVersion(String invocation,String model,String version){jdbc.update("update agent_invocation set model_version=?,version_snapshot=jsonb_set(jsonb_set(version_snapshot,'{model}',to_jsonb(?::text),true),'{modelVersion}',to_jsonb(?::text),true) where id=?",version,model,version,invocation);}
    @Override public void workflowState(String session,String checkpointId,String status){UUID checkpoint=uuid(checkpointId);if(checkpoint==null)return;boolean terminal=Set.of("COMPLETED","FAILED","CANCELLED").contains(status);List<UUID> tasks=jdbc.query("select id from agent_task where adk_session_id=? and current_checkpoint_id=?",(rs,n)->rs.getObject(1,UUID.class),session,checkpoint);jdbc.update("update agent_task set status=?,completed_at="+(terminal?"now()":"null")+",updated_at=now(),version=version+1 where adk_session_id=? and current_checkpoint_id=?",status,session,checkpoint);for(UUID task:tasks)workflowTransition(task,checkpoint,null,status);}
    @Override public void agentStarted(String invocation,String runId,String parentRunId,String name,String branch,long at){UUID run=uuid(runId),parent=uuid(parentRunId);jdbc.update("insert into agent_run(id,invocation_id,parent_run_id,agent_name,branch_path,status,started_at) values (?,?,?,?,?,'RUNNING',?)",run,invocation,parent,name,branch==null?"":branch,new Timestamp(at));createStep(invocation,run,"AGENT",name,at);String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"AGENT_STARTED",Map.of("agentName",name,"runId",runId,"parentRunId",parentRunId==null?"":parentRunId,"branch",branch==null?"":branch));}
    @Override public void agentCompleted(String invocation,String runId,String name,long completed,long duration,long modelCalls,long modelDuration,long input,long output){UUID run=uuid(runId);if(run==null)return;jdbc.update("update agent_run set status='SUCCESS',completed_at=?,duration_ms=?,model_call_count=(select count(*) from model_call where agent_run_id=?),input_tokens=coalesce((select sum(input_tokens) from model_call where agent_run_id=?),0),output_tokens=coalesce((select sum(output_tokens) from model_call where agent_run_id=?),0),version=version+1 where id=?",new Timestamp(completed),duration,run,run,run,run);jdbc.update("update agent_run_step set status='SUCCESS',completed_at=?,duration_ms=? where agent_run_id=? and step_type='AGENT' and status='RUNNING'",new Timestamp(completed),duration,run);String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"AGENT_COMPLETED",Map.of("agentName",name,"runId",runId,"durationMs",duration,"modelDurationMs",modelDuration));}
    @Override public void modelStarted(String invocation,String runId,String agent,long at,long estimatedInput){UUID run=uuid(runId),step=createStep(invocation,run,"MODEL","LLM call",at);jdbc.update("insert into model_call(invocation_id,agent_run_id,step_id,model_name,status,streaming,started_at,input_tokens) values (?,?,?,'agent-default','RUNNING',true,?,?)",invocation,run,step,new Timestamp(at),estimatedInput);jdbc.update("update agent_invocation set model_call_count=model_call_count+1 where id=?",invocation);if(run!=null)jdbc.update("update agent_run set model_call_count=model_call_count+1 where id=?",run);}
    @Override public void modelCompleted(String invocation,String runId,String agent,long completed,long duration,long input,long output,String status,String error){UUID run=uuid(runId);List<UUID> steps=jdbc.query("select step_id from model_call where invocation_id=? and status='RUNNING' and agent_run_id is not distinct from ? order by started_at desc limit 1",(rs,n)->rs.getObject(1,UUID.class),invocation,run);double cost=(input*inputPricePerMillion+output*outputPricePerMillion)/1_000_000d;jdbc.update("update model_call set status=?,completed_at=?,duration_ms=?,input_tokens=?,output_tokens=?,estimated_cost=?,error_message=? where id=(select id from model_call where invocation_id=? and status='RUNNING' and agent_run_id is not distinct from ? order by started_at desc limit 1)",status,new Timestamp(completed),duration,input,output,cost,error,invocation,run);if(!steps.isEmpty())jdbc.update("update agent_run_step set status=?,completed_at=?,duration_ms=?,error_message=? where id=?",status,new Timestamp(completed),duration,error,steps.get(0));}
    @Override public void toolStarted(String invocation,String runId,String agent,String callId,String name,long at,String argumentsJson){
        toolStarted(invocation,runId,agent,callId,name,at,argumentsJson,Map.of());
    }
    @Override public void toolStarted(String invocation,String runId,String agent,String callId,String name,long at,String argumentsJson,Map<String,Object> policy){
        Integer existing=jdbc.queryForObject("select count(*) from tool_execution where invocation_id=? and tool_call_id=?",Integer.class,invocation,callId);
        if(existing!=null&&existing>0){String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"TOOL_REPLAYED",Map.of("agentName",agent,"runId",runId==null?"":runId,"callId",callId,"toolName",name));return;}
        UUID run=uuid(runId),step=createStep(invocation,run,"TOOL",name,at);String idempotencyKey=invocation+":"+callId;
        int timeoutMs=number(policy.get("timeoutMs"),0);
        int inserted=jdbc.update("insert into tool_execution(invocation_id,agent_run_id,step_id,tool_call_id,tool_name,status,arguments_json,arguments_summary,started_at,heartbeat_at,timeout_at,idempotency_key,risk_level,timeout_ms,max_retries,confirmation_required,governance_policy) values (?,?,?,?,?,'RUNNING',cast(? as jsonb),?,?,?,?,?,?,?,?,?,cast(? as jsonb)) on conflict(invocation_id,tool_call_id) do nothing",invocation,run,step,callId,name,argumentsJson,argumentsJson.substring(0,Math.min(1000,argumentsJson.length())),new Timestamp(at),new Timestamp(at),timeoutMs>0?new Timestamp(at+timeoutMs):null,idempotencyKey,Objects.toString(policy.get("riskLevel"),null),timeoutMs,number(policy.get("maxRetries"),0),Boolean.TRUE.equals(policy.get("requiresApproval")),JSON.toJSONString(policy));
        if(inserted==0){jdbc.update("delete from agent_run_step where id=?",step);String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"TOOL_REPLAYED",Map.of("agentName",agent,"runId",runId==null?"":runId,"callId",callId,"toolName",name));return;}
        jdbc.update("insert into tool_execution_attempt(tool_execution_id,attempt_no,status,started_at,request_summary) select id,1,'RUNNING',?,? from tool_execution where invocation_id=? and tool_call_id=? on conflict do nothing",new Timestamp(at),argumentsJson.substring(0,Math.min(1000,argumentsJson.length())),invocation,callId);
        jdbc.update("update agent_invocation set tool_call_count=tool_call_count+1 where id=?",invocation);if(run!=null)jdbc.update("update agent_run set tool_call_count=tool_call_count+1 where id=?",run);String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"TOOL_STARTED",Map.of("agentName",agent,"runId",runId==null?"":runId,"callId",callId,"toolName",name));}
    @Override public void toolRetry(String invocation,String callId,int attempt,long at,String error){Timestamp timestamp=new Timestamp(at);jdbc.update("update tool_execution_attempt set status='FAILED',completed_at=?,duration_ms=extract(epoch from(?-started_at))*1000,error_message=? where tool_execution_id=(select id from tool_execution where invocation_id=? and tool_call_id=?) and status='RUNNING'",timestamp,timestamp,error,invocation,callId);jdbc.update("insert into tool_execution_attempt(tool_execution_id,attempt_no,status,started_at,request_summary) select id,?,'RUNNING',?,arguments_summary from tool_execution where invocation_id=? and tool_call_id=? on conflict do nothing",attempt,timestamp,invocation,callId);jdbc.update("update tool_execution set retry_count=greatest(retry_count,?) where invocation_id=? and tool_call_id=?",attempt-1,invocation,callId);String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"TOOL_RETRY",Map.of("callId",callId,"attemptNo",attempt,"error",error));}
    @Override public String toolCompleted(String invocation,String callId,String status,long completed,long duration,String summary,int retry,String error){
        return tx.execute(transaction->{
        List<Map<String,Object>> current=jdbc.query("select status,result_artifact_id from tool_execution where invocation_id=? and tool_call_id=? for update",(rs,n)->{Map<String,Object> row=new HashMap<>();row.put("status",rs.getString(1));row.put("artifact",rs.getObject(2));return row;},invocation,callId);
        if(current.isEmpty())return "";
        if(!"RUNNING".equals(current.get(0).get("status"))){Object existing=current.get(0).get("artifact");return existing==null?"":existing.toString();}
        UUID artifact=null;
        int resultLimit=jdbc.query("select coalesce((governance_policy->>'maxResultBytes')::int,8000) from tool_execution where invocation_id=? and tool_call_id=?",(rs,n)->rs.getInt(1),invocation,callId).stream().findFirst().orElse(8000);
        if(summary!=null&&summary.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>Math.max(4096,resultLimit)){var conversations=jdbc.query("select c.id,c.workspace_id,c.user_id from conversation c join agent_invocation i on i.adk_session_id=c.adk_session_id where i.id=?",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("conversation",rs.getObject(1,UUID.class));m.put("workspace",rs.getObject(2)==null?"":rs.getObject(2,UUID.class).toString());m.put("user",rs.getObject(3,UUID.class));return m;},invocation);if(!conversations.isEmpty()){artifact=UUID.randomUUID();Map<String,Object> owner=conversations.get(0);UUID workspace=owner.get("workspace").toString().isBlank()?null:UUID.fromString(owner.get("workspace").toString());jdbc.update("insert into artifact(id,workspace_id,conversation_id,invocation_id,lineage_id,artifact_type,name,mime_type,storage_type,content_text,content_hash,size_bytes,created_by) values (?,?,?,?,?,'TOOL_RESULT','Tool Result','application/json','DATABASE',?,?,?,?)",artifact,workspace,owner.get("conversation"),invocation,artifact,summary,hash(summary),summary.getBytes(java.nio.charset.StandardCharsets.UTF_8).length,owner.get("user"));}}
        String shortSummary=summary==null?null:summary.substring(0,Math.min(1000,summary.length()));List<UUID> steps=jdbc.query("select step_id from tool_execution where invocation_id=? and tool_call_id=?",(rs,n)->rs.getObject(1,UUID.class),invocation,callId);
        jdbc.update("update tool_execution set status=?,completed_at=?,duration_ms=?,result_summary=?,result_artifact_id=?,retry_count=greatest(retry_count,?),error_message=? where invocation_id=? and tool_call_id=?",status,new Timestamp(completed),duration,shortSummary,artifact,retry,error,invocation,callId);
        jdbc.update("update tool_execution_attempt set status=?,completed_at=?,duration_ms=extract(epoch from(?-started_at))*1000,result_summary=?,error_message=? where tool_execution_id=(select id from tool_execution where invocation_id=? and tool_call_id=?) and status='RUNNING'",status,new Timestamp(completed),new Timestamp(completed),shortSummary,error,invocation,callId);
        if(artifact!=null)jdbc.update("update capability_execution set result_artifact_id=? where invocation_id=? and parent_tool_call_id=? and action='EXECUTE'",artifact,invocation,callId);
        if(!steps.isEmpty())jdbc.update("update agent_run_step set status=?,completed_at=?,duration_ms=?,output_summary=?,error_message=? where id=?",status,new Timestamp(completed),duration,shortSummary,error,steps.get(0));String s=session(invocation);if(s!=null)runtimeEvent(s,invocation,"TOOL_COMPLETED",Map.of("callId",callId,"status",status,"durationMs",duration,"retryCount",retry,"artifactId",artifact==null?"":artifact.toString()));
        return artifact==null?"":artifact.toString();
        });
    }
    @Override public void capabilitySearch(String searchId,String invocation,String runId,String agent,String parentCall,String snapshot,String query,List<String> types,int registrySize,List<Map<String,Object>> candidates,long started,long completed,long duration,String status,String error){UUID id=uuid(searchId);jdbc.update("insert into capability_search(id,invocation_id,agent_run_id,parent_tool_call_id,snapshot_id,agent_name,query,requested_types,registry_size,result_count,status,started_at,completed_at,duration_ms,error_message) values (?,?,?,?,?,?,?,cast(? as jsonb),?,?,?, ?,?,?,?)",id,invocation,uuid(runId),parentCall,snapshot,agent,query,JSON.toJSONString(types),registrySize,candidates.size(),status,new Timestamp(started),new Timestamp(completed),duration,error);int rank=0;for(Map<String,Object> c:candidates){rank++;jdbc.update("insert into capability_search_candidate(search_id,rank_no,capability_id,capability_type,capability_group,capability_name,capability_version,risk_level,score,schema_version,content_version) values (?,?,?,?,?,?,?,?,?,?,?)",id,rank,c.get("capabilityId"),c.get("type"),c.get("group"),c.get("name"),number(c.get("version"),1),Objects.toString(c.get("riskLevel"),""),decimal(c.get("score")),c.get("schemaVersion"),c.get("contentVersion"));}}
    @Override public void capabilityExecutionStarted(String id,String invocation,String runId,String agent,String parentCall,String snapshot,String action,Map<String,Object>d,String resource,Map<String,Object>arguments,long started){jdbc.update("insert into capability_execution(id,invocation_id,agent_run_id,parent_tool_call_id,snapshot_id,action,capability_id,capability_type,capability_group,capability_name,capability_version,risk_level,resource_path,arguments,status,started_at,schema_version,content_version) values (?,?,?,?,?,?,?,?,?,?,?,?,?,cast(? as jsonb),'RUNNING',?,?,?)",uuid(id),invocation,uuid(runId),parentCall,snapshot,action,d.get("capabilityId"),d.get("capabilityType"),d.get("capabilityGroup"),d.get("capabilityName"),number(d.get("capabilityVersion"),1),d.get("riskLevel"),resource,JSON.toJSONString(arguments),new Timestamp(started),d.get("schemaVersion"),d.get("contentVersion"));jdbc.update("update capability_search_candidate set selected=true where search_id=(select id from capability_search where invocation_id=? and snapshot_id=?) and capability_id=?",invocation,snapshot,d.get("capabilityId"));}
    @Override public void capabilityExecutionCompleted(String id,String status,long completed,long duration,String summary,long size,String hash,int retry,String error){jdbc.update("update capability_execution set status=?,completed_at=?,duration_ms=?,result_summary=?,result_size=?,result_hash=?,retry_count=?,error_message=? where id=?",status,new Timestamp(completed),duration,summary,size,hash,retry,error,uuid(id));}
    @Override public void runtimeEvent(String session,String invocation,String type,Map<String,Object> payload){tx.executeWithoutResult(status->{jdbc.query("select pg_advisory_xact_lock(hashtext(?))",rs->null,session);Long seq=jdbc.queryForObject("select coalesce(max(sequence_no),0)+1 from agent_runtime_event where session_id=?",Long.class,session);jdbc.update("insert into agent_runtime_event(session_id,invocation_id,sequence_no,event_type,payload) values (?,?,?,?,cast(? as jsonb))",session,invocation,seq,type,JSON.toJSONString(payload));});}
    @Override public List<Map<String,Object>> listBySession(String username,String session){return jdbc.query("select i.* from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=? and i.adk_session_id=? order by i.started_at desc",this::invocationMap,username,session);}
    @Override public List<Map<String,Object>> listRecent(String username,int limit){return jdbc.query("select i.* from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=? order by i.started_at desc limit ?",this::invocationMap,username,Math.max(1,Math.min(limit,500)));}
    @Override public Map<String,Object> detail(String username,String invocation){List<Map<String,Object>> rows=jdbc.query("select i.* from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=? and i.id=?",this::invocationMap,username,invocation);if(rows.isEmpty())return Map.of();Map<String,Object> result=new LinkedHashMap<>(rows.get(0));result.put("agents",jdbc.query("select r.*,coalesce((select sum(duration_ms) from model_call m where m.agent_run_id=r.id),0) model_duration from agent_run r where invocation_id=? order by started_at",(rs,n)->{Map<String,Object> a=new LinkedHashMap<>();a.put("name",rs.getString("agent_name"));a.put("startedAt",millis(rs,"started_at"));a.put("completedAt",millis(rs,"completed_at"));a.put("durationMs",rs.getLong("duration_ms"));a.put("modelCalls",rs.getLong("model_call_count"));a.put("modelDurationMs",rs.getLong("model_duration"));a.put("inputTokens",rs.getLong("input_tokens"));a.put("outputTokens",rs.getLong("output_tokens"));a.put("totalTokens",rs.getLong("input_tokens")+rs.getLong("output_tokens"));a.put("tokensEstimated",false);return a;},invocation));result.put("models",jdbc.query("select m.*,r.agent_name from model_call m left join agent_run r on r.id=m.agent_run_id where m.invocation_id=? order by m.started_at",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",rs.getString("id"));m.put("agentName",rs.getString("agent_name"));m.put("modelName",rs.getString("model_name"));m.put("status",rs.getString("status"));m.put("startedAt",millis(rs,"started_at"));m.put("completedAt",millis(rs,"completed_at"));m.put("durationMs",rs.getLong("duration_ms"));m.put("inputTokens",rs.getLong("input_tokens"));m.put("outputTokens",rs.getLong("output_tokens"));m.put("error",rs.getString("error_message"));return m;},invocation));result.put("tools",jdbc.query("select t.*,r.agent_name from tool_execution t left join agent_run r on r.id=t.agent_run_id where t.invocation_id=? order by t.started_at",(rs,n)->{Map<String,Object> t=new LinkedHashMap<>();t.put("callId",rs.getString("tool_call_id"));t.put("agentName",Objects.toString(rs.getString("agent_name"),""));t.put("toolName",rs.getString("tool_name"));t.put("startedAt",millis(rs,"started_at"));t.put("completedAt",millis(rs,"completed_at"));t.put("durationMs",rs.getLong("duration_ms"));t.put("status",rs.getString("status"));t.put("arguments",rs.getString("arguments_summary"));t.put("summary",rs.getString("result_summary"));t.put("retryCount",rs.getInt("retry_count"));t.put("error",rs.getString("error_message"));t.put("attempts",jdbc.queryForList("select attempt_no,status,started_at,completed_at,duration_ms,result_summary,error_message from tool_execution_attempt where tool_execution_id=? order by attempt_no",rs.getObject("id",UUID.class)));return t;},invocation));List<Map<String,Object>> events=jdbc.query("select sequence_no,event_type,event_time,payload from agent_runtime_event where invocation_id=? order by sequence_no",(rs,n)->{Map<String,Object> e=new LinkedHashMap<>();e.put("sequenceNo",rs.getLong("sequence_no"));e.put("eventType",rs.getString("event_type"));e.put("eventTime",millis(rs,"event_time"));e.put("payload",JSON.parseObject(rs.getString("payload"),Map.class));return e;},invocation);result.put("events",events);result.put("compressions",eventPayloads(events,"CONTEXT_COMPRESSED"));result.put("modelDecisions",eventPayloads(events,"MODEL_ROUTED"));result.put("capabilityEvents",events.stream().filter(e->String.valueOf(e.get("eventType")).startsWith("CAPABILITY_")).map(e->{Map<String,Object> p=new LinkedHashMap<>((Map<String,Object>)e.get("payload"));p.put("event",String.valueOf(e.get("eventType")).substring("CAPABILITY_".length()));return p;}).toList());result.put("capabilityFeedback",jdbc.queryForList("select search_id,capability_id,judgment,note,created_at from capability_feedback where invocation_id=? order by created_at",invocation));return result;}
    @Override public List<Map<String,Object>> agentRuns(String username,String invocation){
        String sql="""
                select r.*,i.root_agent_name,
                  case when r.agent_name=i.root_agent_name then (select count(*) from model_call m where m.invocation_id=r.invocation_id) else r.model_call_count end display_model_calls,
                  case when r.agent_name=i.root_agent_name then (select count(*) from tool_execution t where t.invocation_id=r.invocation_id) else r.tool_call_count end display_tool_calls,
                  case when r.agent_name=i.root_agent_name then (select coalesce(sum(m.input_tokens),0) from model_call m where m.invocation_id=r.invocation_id) else r.input_tokens end display_input_tokens,
                  case when r.agent_name=i.root_agent_name then (select coalesce(sum(m.output_tokens),0) from model_call m where m.invocation_id=r.invocation_id) else r.output_tokens end display_output_tokens
                from agent_run r join agent_invocation i on i.id=r.invocation_id
                join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id
                where u.username=? and r.invocation_id=? order by r.started_at
                """;
        return jdbc.query(sql,(rs,n)->{Map<String,Object> r=new LinkedHashMap<>();boolean root=rs.getString("agent_name").equals(rs.getString("root_agent_name"));r.put("runId",rs.getString("id"));r.put("parentRunId",Objects.toString(rs.getString("parent_run_id"),""));r.put("agentName",rs.getString("agent_name"));r.put("role",root?"ROOT":"SUBAGENT");r.put("status",rs.getString("status"));r.put("startedAt",millis(rs,"started_at"));r.put("completedAt",millis(rs,"completed_at"));r.put("durationMs",rs.getLong("duration_ms"));r.put("modelCallCount",rs.getInt("display_model_calls"));r.put("toolCallCount",rs.getInt("display_tool_calls"));r.put("inputTokens",rs.getLong("display_input_tokens"));r.put("outputTokens",rs.getLong("display_output_tokens"));r.put("aggregated",root);r.put("retryCount",rs.getInt("retry_count"));r.put("error",rs.getString("error_message"));return r;},username,invocation);
    }
    @Override public List<Map<String,Object>> capabilitySearches(String username,String invocation){if(!owned(username,invocation))return List.of();return jdbc.query("select * from capability_search where invocation_id=? order by started_at",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();UUID id=rs.getObject("id",UUID.class);m.put("id",id.toString());m.put("snapshotId",rs.getString("snapshot_id"));m.put("parentToolCallId",Objects.toString(rs.getString("parent_tool_call_id"),""));m.put("agentName",rs.getString("agent_name"));m.put("query",rs.getString("query"));m.put("requestedTypes",JSON.parseArray(rs.getString("requested_types")));m.put("registrySize",rs.getInt("registry_size"));m.put("resultCount",rs.getInt("result_count"));m.put("status",rs.getString("status"));m.put("startedAt",millis(rs,"started_at"));m.put("completedAt",millis(rs,"completed_at"));m.put("durationMs",rs.getLong("duration_ms"));m.put("error",Objects.toString(rs.getString("error_message"),""));m.put("candidates",jdbc.query("select * from capability_search_candidate where search_id=? order by rank_no",(cr,row)->Map.of("rank",cr.getInt("rank_no"),"capabilityId",cr.getString("capability_id"),"type",cr.getString("capability_type"),"group",cr.getString("capability_group"),"name",cr.getString("capability_name"),"version",cr.getInt("capability_version"),"riskLevel",cr.getString("risk_level"),"score",cr.getDouble("score"),"selected",cr.getBoolean("selected")),id));return m;},invocation);}
    @Override public List<Map<String,Object>> capabilityExecutions(String username,String invocation){if(!owned(username,invocation))return List.of();return jdbc.query("select * from capability_execution where invocation_id=? order by started_at",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",rs.getString("id"));m.put("snapshotId",rs.getString("snapshot_id"));m.put("parentToolCallId",Objects.toString(rs.getString("parent_tool_call_id"),""));m.put("action",rs.getString("action"));m.put("capabilityId",rs.getString("capability_id"));m.put("type",rs.getString("capability_type"));m.put("group",rs.getString("capability_group"));m.put("name",rs.getString("capability_name"));m.put("version",rs.getInt("capability_version"));m.put("riskLevel",rs.getString("risk_level"));m.put("resourcePath",Objects.toString(rs.getString("resource_path"),""));m.put("arguments",JSON.parseObject(rs.getString("arguments"),Map.class));m.put("resultSummary",Objects.toString(rs.getString("result_summary"),""));m.put("resultSize",rs.getLong("result_size"));m.put("resultHash",Objects.toString(rs.getString("result_hash"),""));m.put("artifactId",Objects.toString(rs.getString("result_artifact_id"),""));m.put("status",rs.getString("status"));m.put("startedAt",millis(rs,"started_at"));m.put("completedAt",millis(rs,"completed_at"));m.put("durationMs",rs.getLong("duration_ms"));m.put("retryCount",rs.getInt("retry_count"));m.put("error",Objects.toString(rs.getString("error_message"),""));return m;},invocation);}
    @Override public List<Map<String,Object>> waterfall(String username,String invocation){
        if(!owned(username,invocation))return List.of();
        String sql="select id::text item_id,parent_run_id::text parent_id,agent_name item_name,'AGENT' item_type,status,started_at,completed_at,duration_ms,input_tokens,output_tokens from agent_run where invocation_id=? " +
                "union all select id::text,agent_run_id::text,model_name,'MODEL',status,started_at,completed_at,duration_ms,input_tokens,output_tokens from model_call where invocation_id=? " +
                "union all select id::text,agent_run_id::text,tool_name,'TOOL',status,started_at,completed_at,duration_ms,0,0 from tool_execution where invocation_id=? " +
                "union all select s.id::text,coalesce(t.id::text,s.agent_run_id::text),concat('SEARCH · ',left(s.query,80)),'CAPABILITY',s.status,s.started_at,s.completed_at,s.duration_ms,0,0 from capability_search s left join tool_execution t on t.invocation_id=s.invocation_id and t.tool_call_id=s.parent_tool_call_id where s.invocation_id=? " +
                "union all select e.id::text,coalesce(t.id::text,e.agent_run_id::text),concat(e.action,' · ',e.capability_name),'CAPABILITY',e.status,e.started_at,e.completed_at,e.duration_ms,0,0 from capability_execution e left join tool_execution t on t.invocation_id=e.invocation_id and t.tool_call_id=e.parent_tool_call_id where e.invocation_id=? order by started_at";
        return jdbc.query(sql,(rs,n)->{Map<String,Object> item=new LinkedHashMap<>();item.put("id",rs.getString("item_id"));item.put("parentId",Objects.toString(rs.getString("parent_id"),""));item.put("name",rs.getString("item_name"));item.put("type",rs.getString("item_type"));item.put("status",rs.getString("status"));item.put("startedAt",millis(rs,"started_at"));item.put("completedAt",millis(rs,"completed_at"));item.put("durationMs",rs.getLong("duration_ms"));item.put("inputTokens",rs.getLong("input_tokens"));item.put("outputTokens",rs.getLong("output_tokens"));return item;},invocation,invocation,invocation,invocation,invocation);
    }
    @Override public void capabilityFeedback(String username,String invocation,String searchId,String capabilityId,String judgment,String note){if(!owned(username,invocation))throw new cn.bugstack.ai.types.exception.AppException("INVOCATION_FORBIDDEN","Invocation 不存在或无权访问");String normalized=Objects.toString(judgment,"").toUpperCase(Locale.ROOT);if(!Set.of("REQUIRED_MISSED","WRONG_SELECTION","IMPACTED_OUTPUT","NO_IMPACT").contains(normalized))throw new IllegalArgumentException("Unsupported capability judgment");String safe=Objects.toString(note,"");if(safe.length()>2000)safe=safe.substring(0,2000);jdbc.update("insert into capability_feedback(invocation_id,search_id,capability_id,judgment,note,created_by) values (?,?,?,?,?,(select id from app_user where username=?))",invocation,uuid(searchId),capabilityId,normalized,safe,username);}
    @Override public Map<String,Object> executionStructure(String username,String invocation){List<Integer> owned=jdbc.query("select 1 from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=? and i.id=?",(rs,n)->1,username,invocation);if(owned.isEmpty())return Map.of();Map<String,Object> result=new LinkedHashMap<>();List<Map<String,Object>> tasks=jdbc.query("select t.id,t.title,t.task_type,t.status,t.created_at,t.updated_at,t.completed_at,t.version from agent_task t join agent_invocation i on i.task_id=t.id where i.id=?",(rs,n)->{Map<String,Object> t=new LinkedHashMap<>();t.put("id",rs.getString("id"));t.put("title",rs.getString("title"));t.put("taskType",rs.getString("task_type"));t.put("status",rs.getString("status"));t.put("createdAt",millis(rs,"created_at"));t.put("updatedAt",millis(rs,"updated_at"));t.put("completedAt",millis(rs,"completed_at"));t.put("version",rs.getLong("version"));return t;},invocation);result.put("task",tasks.isEmpty()?null:tasks.get(0));result.put("steps",jdbc.query("select s.*,r.agent_name from agent_run_step s left join agent_run r on r.id=s.agent_run_id where s.invocation_id=? order by s.sequence_no",(rs,n)->{Map<String,Object> s=new LinkedHashMap<>();s.put("id",rs.getString("id"));s.put("sequenceNo",rs.getLong("sequence_no"));s.put("stepType",rs.getString("step_type"));s.put("stepName",rs.getString("step_name"));s.put("agentName",Objects.toString(rs.getString("agent_name"),""));s.put("status",rs.getString("status"));s.put("startedAt",millis(rs,"started_at"));s.put("completedAt",millis(rs,"completed_at"));s.put("durationMs",rs.getLong("duration_ms"));s.put("retryCount",rs.getInt("retry_count"));s.put("outputSummary",rs.getString("output_summary"));s.put("error",rs.getString("error_message"));return s;},invocation));return result;}
    @Override public Map<String,Object> workflowDetail(String username,String taskId){UUID task=uuid(taskId);if(task==null)return Map.of();List<Map<String,Object>> owned=jdbc.query("select t.*,u.username from agent_task t join conversation c on c.id=t.conversation_id join app_user u on u.id=c.user_id where t.id=? and u.username=?",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("taskId",rs.getString("id"));m.put("name",rs.getString("title"));m.put("status",rs.getString("status"));m.put("createdAt",millis(rs,"created_at"));m.put("completedAt",millis(rs,"completed_at"));m.put("wallDurationMs",Math.max(0,(rs.getTimestamp("completed_at")==null?System.currentTimeMillis():rs.getTimestamp("completed_at").getTime())-rs.getTimestamp("created_at").getTime()));return m;},task,username);if(owned.isEmpty())return Map.of();Map<String,Object> result=new LinkedHashMap<>(owned.get(0));
        Map<String,Object> totals=jdbc.queryForObject("select count(*) invocations,coalesce(sum(duration_ms),0) invocation_ms,coalesce(sum(input_tokens),0) input_tokens,coalesce(sum(output_tokens),0) output_tokens,count(*) filter(where status='SUCCESS') successes,count(*) filter(where status in('ERROR','FAILED','INTERRUPTED')) errors from agent_invocation where task_id=?",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("invocations",rs.getLong("invocations"));m.put("computeDurationMs",rs.getLong("invocation_ms"));m.put("inputTokens",rs.getLong("input_tokens"));m.put("outputTokens",rs.getLong("output_tokens"));m.put("successes",rs.getLong("successes"));m.put("errors",rs.getLong("errors"));return m;},task);result.putAll(totals);
        Long modelMs=jdbc.queryForObject("select coalesce(sum(m.duration_ms),0) from model_call m join agent_invocation i on i.id=m.invocation_id where i.task_id=?",Long.class,task);Long toolMs=jdbc.queryForObject("select coalesce(sum(x.duration_ms),0) from tool_execution x join agent_invocation i on i.id=x.invocation_id where i.task_id=?",Long.class,task);result.put("modelDurationMs",modelMs);result.put("toolDurationMs",toolMs);
        Long userWait=jdbc.queryForObject("select coalesce(sum(extract(epoch from(next_at-occurred_at))*1000),0)::bigint from(select occurred_at,to_status,lead(occurred_at) over(order by sequence_no) next_at from workflow_state_transition where task_id=?)x where to_status in('WAITING_APPROVAL','WAITING_TOOL_APPROVAL') and next_at is not null",Long.class,task);Long queueWait=jdbc.queryForObject("select coalesce(sum(extract(epoch from(claimed_at-created_at))*1000),0)::bigint from workflow_recovery_job where checkpoint_id=(select current_checkpoint_id from agent_task where id=?) and claimed_at is not null",Long.class,task);result.put("userWaitDurationMs",userWait);result.put("queueWaitDurationMs",queueWait);
        result.put("estimatedCost",jdbc.queryForObject("select coalesce(sum(estimated_cost),0) from agent_invocation where task_id=?",java.math.BigDecimal.class,task));
        result.put("toolStats",jdbc.queryForMap("select count(*) total,count(*) filter(where x.status='SUCCESS') success,coalesce(sum(x.retry_count),0) retries from tool_execution x join agent_invocation i on i.id=x.invocation_id where i.task_id=?",task));result.put("artifactCount",jdbc.queryForObject("select count(*) from artifact a join agent_invocation i on i.id=a.invocation_id where i.task_id=?",Long.class,task));
        result.put("artifacts",jdbc.queryForList("select a.id,a.parent_artifact_id,a.lineage_id,a.branch_name,a.artifact_type,a.name,a.version_no,a.status,a.size_bytes,a.created_at,a.invocation_id from artifact a join agent_invocation i on i.id=a.invocation_id where i.task_id=? order by a.created_at",task));
        result.put("finalResult",jdbc.query("select m.content_text from conversation_message m join agent_task t on t.conversation_id=m.conversation_id where t.id=? and m.role='assistant' order by m.sequence_no desc limit 1",(rs,n)->Objects.toString(rs.getString(1),""),task).stream().findFirst().orElse(""));
        result.put("transitions",jdbc.queryForList("select sequence_no,from_status,to_status,checkpoint_id,invocation_id,occurred_at from workflow_state_transition where task_id=? order by sequence_no",task));result.put("invocations",jdbc.query("select i.* from agent_invocation i where i.task_id=? order by i.started_at",this::invocationMap,task));return result;}
    @Override public Map<String,Object> summary(String username){return summary(username,null);}
    @Override public Map<String,Object> summary(String username,String sessionId){String base="select count(*) total,count(*) filter(where i.status='SUCCESS') success,count(*) filter(where i.status in ('ERROR','FAILED')) errors,count(*) filter(where i.status='RUNNING') active,coalesce(avg(i.duration_ms),0) avg_duration,coalesce(sum(i.input_tokens),0) input_tokens,coalesce(sum(i.output_tokens),0) output_tokens from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=?";String sql=sessionId==null||sessionId.isBlank()?base:base+" and i.adk_session_id=?";Object[] args=sessionId==null||sessionId.isBlank()?new Object[]{username}:new Object[]{username,sessionId};return jdbc.queryForObject(sql,(rs,n)->Map.of("total",rs.getLong("total"),"success",rs.getLong("success"),"errors",rs.getLong("errors"),"active",rs.getLong("active"),"averageDurationMs",rs.getLong("avg_duration"),"inputTokens",rs.getLong("input_tokens"),"outputTokens",rs.getLong("output_tokens"),"totalTokens",rs.getLong("input_tokens")+rs.getLong("output_tokens"),"registeredTools",List.of()),args);}
    private String session(String invocation){List<String> values=jdbc.query("select adk_session_id from agent_invocation where id=?",(rs,n)->rs.getString(1),invocation);return values.isEmpty()?null:values.get(0);}
    private boolean owned(String username,String invocation){return !jdbc.query("select 1 from agent_invocation i join conversation c on c.adk_session_id=i.adk_session_id join app_user u on u.id=c.user_id where u.username=? and i.id=?",(rs,n)->1,username,invocation).isEmpty();}
    private UUID createStep(String invocation,UUID run,String type,String name,long at){return tx.execute(status->{jdbc.query("select pg_advisory_xact_lock(hashtext(?))",rs->null,invocation);Long seq=jdbc.queryForObject("select coalesce(max(sequence_no),0)+1 from agent_run_step where invocation_id=?",Long.class,invocation);UUID id=UUID.randomUUID();jdbc.update("insert into agent_run_step(id,invocation_id,agent_run_id,sequence_no,step_type,step_name,status,started_at) values (?,?,?,?,?,?,'RUNNING',?)",id,invocation,run,seq,type,name,new Timestamp(at));return id;});}
    private void workflowTransition(UUID task,UUID checkpoint,String invocation,String to){tx.executeWithoutResult(status->{jdbc.query("select pg_advisory_xact_lock(hashtext(?))",rs->null,task.toString());Long seq=jdbc.queryForObject("select coalesce(max(sequence_no),0)+1 from workflow_state_transition where task_id=?",Long.class,task);String from=jdbc.query("select to_status from workflow_state_transition where task_id=? order by sequence_no desc limit 1",(rs,n)->rs.getString(1),task).stream().findFirst().orElse(null);if(!Objects.equals(from,to))jdbc.update("insert into workflow_state_transition(task_id,sequence_no,checkpoint_id,invocation_id,from_status,to_status) values (?,?,?,?,?,?)",task,seq,checkpoint,invocation,from,to);});}
    private static UUID uuid(String value){try{return value==null||value.isBlank()?null:UUID.fromString(value);}catch(IllegalArgumentException ignored){return null;}}
    private static int number(Object value,int fallback){return value instanceof Number n?n.intValue():fallback;}
    private static double decimal(Object value){return value instanceof Number n?n.doubleValue():0;}
    private static String hash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private Map<String,Object> invocationMap(ResultSet rs,int row)throws SQLException{Map<String,Object> m=new LinkedHashMap<>();String id=rs.getString("id"),taskId=Objects.toString(rs.getString("task_id"),"");m.put("invocationId",id);m.put("taskId",taskId);m.put("workflowName",taskTitle(taskId));m.put("sessionId",rs.getString("adk_session_id"));m.put("userId","");m.put("rootAgent",rs.getString("root_agent_name"));m.put("status",rs.getString("status"));m.put("startedAt",millis(rs,"started_at"));m.put("completedAt",millis(rs,"completed_at"));m.put("durationMs",rs.getLong("duration_ms"));m.put("inputTokens",rs.getLong("input_tokens"));m.put("outputTokens",rs.getLong("output_tokens"));m.put("totalTokens",rs.getLong("input_tokens")+rs.getLong("output_tokens"));m.put("eventCount",count("agent_runtime_event",id));m.put("agentCount",count("agent_run",id));m.put("toolCount",count("tool_execution",id));m.put("compressionCount",0);m.put("tokensEstimated",false);m.put("error",rs.getString("error_message"));return m;}
    private String taskTitle(String taskId){UUID task=uuid(taskId);if(task==null)return "";List<String> titles=jdbc.query("select title from agent_task where id=?",(rs,n)->rs.getString(1),task);return titles.isEmpty()?"":titles.get(0);}
    private int count(String table,String invocation){return Optional.ofNullable(jdbc.queryForObject("select count(*) from "+table+" where invocation_id=?",Integer.class,invocation)).orElse(0);}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> eventPayloads(List<Map<String,Object>> events,String type){return events.stream().filter(e->type.equals(e.get("eventType"))).map(e->(Map<String,Object>)e.get("payload")).toList();}
    private Long millis(ResultSet rs,String name)throws SQLException{Timestamp t=rs.getTimestamp(name);return t==null?0L:t.toInstant().toEpochMilli();}
}
